package main

import (
	"crypto/rand"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"time"
)

// WebhookEvent представляет стандартный каноничный конверт исходящего вебхука.
type WebhookEvent struct {
	ID        string `json:"id"`
	Type      string `json:"type"`
	CreatedAt int64  `json:"created_at"`
	Payload   any    `json:"payload"`
}

// PaymentPayload — пример доменных данных события.
type PaymentPayload struct {
	OrderID  string  `json:"order_id"`
	Amount   float64 `json:"amount"`
	Currency string  `json:"currency"`
	Status   string  `json:"status"`
}

// GenerateWebhookSecret создает криптографически стойкий секретный ключ для клиента.
func GenerateWebhookSecret(byteLen int) (string, error) {
	b := make([]byte, byteLen)
	if _, err := rand.Read(b); err != nil {
		return "", fmt.Errorf("crypto/rand failure: %w", err)
	}
	return "whsec_" + base64.RawURLEncoding.EncodeToString(b), nil
}

func main() {
	secret, err := GenerateWebhookSecret(32)
	if err != nil {
		panic(err)
	}
	fmt.Printf("Generated Client Secret: %s\n", secret)

	event := WebhookEvent{
		ID:        "evt_01HZX8N29KQW4VBM8YZ",
		Type:      "order.payment.succeeded",
		CreatedAt: time.Now().UTC().Unix(),
		Payload: PaymentPayload{
			OrderID:  "ord_994821",
			Amount:   2490.50,
			Currency: "RUB",
			Status:   "COMPLETED",
		},
	}

	body, err := json.MarshalIndent(event, "", "  ")
	if err != nil {
		panic(err)
	}
	fmt.Printf("Event Envelope JSON:\n%s\n", string(body))
}

package main

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"net/http"
	"time"
)

type DeliveryAction string

const (
	ActionSuccess     DeliveryAction = "SUCCESS"
	ActionRetry       DeliveryAction = "RETRY"
	ActionDrop        DeliveryAction = "DROP_PERMANENT"
	ActionUnsubscribe DeliveryAction = "UNSUBSCRIBE"
)

type DeliveryResult struct {
	StatusCode int
	Action     DeliveryAction
	Message    string
	Err        error
}

func SendWebhook(ctx context.Context, client *http.Client, targetURL string, payload []byte) DeliveryResult {
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, targetURL, bytes.NewReader(payload))
	if err != nil {
		return DeliveryResult{Action: ActionDrop, Message: "Malformed request", Err: err}
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("User-Agent", "GoWorkout-Webhook-Dispatcher/1.0")

	resp, err := client.Do(req)
	if err != nil {
		return DeliveryResult{Action: ActionRetry, Message: "Network/Timeout error", Err: err}
	}
	defer resp.Body.Close()

	bodySnippet, _ := io.ReadAll(io.LimitReader(resp.Body, 4096))

	switch {
	case resp.StatusCode >= 200 && resp.StatusCode < 300:
		return DeliveryResult{StatusCode: resp.StatusCode, Action: ActionSuccess, Message: string(bodySnippet)}
	case resp.StatusCode == http.StatusGone:
		return DeliveryResult{StatusCode: resp.StatusCode, Action: ActionUnsubscribe, Message: "Client returned 410 Gone: permanently removed"}
	case resp.StatusCode == http.StatusTooManyRequests || resp.StatusCode >= 500:
		return DeliveryResult{StatusCode: resp.StatusCode, Action: ActionRetry, Message: fmt.Sprintf("Temporary server error (%d)", resp.StatusCode)}
	case resp.StatusCode >= 400 && resp.StatusCode < 500:
		return DeliveryResult{StatusCode: resp.StatusCode, Action: ActionDrop, Message: fmt.Sprintf("Permanent client error (%d)", resp.StatusCode)}
	default:
		return DeliveryResult{StatusCode: resp.StatusCode, Action: ActionRetry, Message: fmt.Sprintf("Unexpected status (%d)", resp.StatusCode)}
	}
}

func main() {
	client := &http.Client{Timeout: 3 * time.Second}
	res := SendWebhook(context.Background(), client, "https://httpbin.org/status/410", []byte(`{"ping": true}`))
	fmt.Printf("Status: %d | Action: %s | Info: %s\n", res.StatusCode, res.Action, res.Message)

	res503 := SendWebhook(context.Background(), client, "https://httpbin.org/status/503", []byte(`{"ping": true}`))
	fmt.Printf("Status: %d | Action: %s | Info: %s\n", res503.StatusCode, res503.Action, res503.Message)
}

package main

import (
	"bytes"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
)

func ComputeHMACSHA256(payload []byte, secret string) string {
	mac := hmac.New(sha256.New, []byte(secret))
	mac.Write(payload)
	return hex.EncodeToString(mac.Sum(nil))
}

func SendSignedWebhook(targetURL string, payload []byte, secret string) (*http.Response, error) {
	signature := ComputeHMACSHA256(payload, secret)

	req, err := http.NewRequest(http.MethodPost, targetURL, bytes.NewReader(payload))
	if err != nil {
		return nil, err
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("X-Webhook-Signature", signature)

	client := &http.Client{}
	return client.Do(req)
}

func main() {
	secret := "whsec_super_secret_signing_key_2026"
	payload := []byte(`{"id":"evt_101","event":"user.signup","email":"dev@ozon.ru"}`)

	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		recSignature := r.Header.Get("X-Webhook-Signature")
		body, _ := io.ReadAll(r.Body)

		expectedSignature := ComputeHMACSHA256(body, secret)
		if recSignature == expectedSignature {
			fmt.Printf("Receiver: Signature verified successfully! [sig=%s]\n", recSignature[:16]+"...")
			w.WriteHeader(http.StatusOK)
		} else {
			fmt.Printf("Receiver: Signature mismatch!\n")
			w.WriteHeader(http.StatusUnauthorized)
		}
	}))
	defer ts.Close()

	resp, err := SendSignedWebhook(ts.URL, payload, secret)
	if err != nil {
		panic(err)
	}
	defer resp.Body.Close()

	fmt.Printf("Response Status: %d %s\n", resp.StatusCode, resp.Status)
}

package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"sync"
	"time"
)

type OrderPaidEvent struct {
	OrderID   string  `json:"order_id"`
	UserID    string  `json:"user_id"`
	Amount    float64 `json:"amount"`
	Timestamp int64   `json:"timestamp"`
}

type DeliveryTask struct {
	TargetURL string
	Event     OrderPaidEvent
}

type WebhookDispatcher struct {
	taskChan chan DeliveryTask
	wg       sync.WaitGroup
	client   *http.Client
}

func NewWebhookDispatcher(bufferSize int, workers int) *WebhookDispatcher {
	d := &WebhookDispatcher{
		taskChan: make(chan DeliveryTask, bufferSize),
		client:   &http.Client{Timeout: 5 * time.Second},
	}
	for i := 1; i <= workers; i++ {
		d.wg.Add(1)
		go d.worker(i)
	}
	return d
}

func (d *WebhookDispatcher) worker(id int) {
	defer d.wg.Done()
	for task := range d.taskChan {
		d.deliver(id, task)
	}
}

func (d *WebhookDispatcher) deliver(workerID int, task DeliveryTask) {
	body, err := json.Marshal(task.Event)
	if err != nil {
		fmt.Printf("[Worker %d] Serialization error: %v\n", workerID, err)
		return
	}

	req, err := http.NewRequest(http.MethodPost, task.TargetURL, bytes.NewReader(body))
	if err != nil {
		fmt.Printf("[Worker %d] Request creation error: %v\n", workerID, err)
		return
	}
	req.Header.Set("Content-Type", "application/json")

	resp, err := d.client.Do(req)
	if err != nil {
		fmt.Printf("[Worker %d] Failed to deliver to %s: %v\n", workerID, task.TargetURL, err)
		return
	}
	resp.Body.Close()
	fmt.Printf("[Worker %d] Successfully delivered order %s -> status %d\n", workerID, task.Event.OrderID, resp.StatusCode)
}

func (d *WebhookDispatcher) Enqueue(task DeliveryTask) {
	d.taskChan <- task
}

func (d *WebhookDispatcher) Stop() {
	close(d.taskChan)
	d.wg.Wait()
}

func main() {
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
	}))
	defer ts.Close()

	dispatcher := NewWebhookDispatcher(100, 3)

	for i := 1; i <= 5; i++ {
		dispatcher.Enqueue(DeliveryTask{
			TargetURL: ts.URL,
			Event: OrderPaidEvent{
				OrderID:   fmt.Sprintf("ord_%d", 100+i),
				UserID:    fmt.Sprintf("usr_%d", i),
				Amount:    float64(i * 1500),
				Timestamp: time.Now().Unix(),
			},
		})
	}

	dispatcher.Stop()
	fmt.Println("Dispatcher gracefully stopped.")
}

