import (
	"encoding/json"
	"errors"
	"fmt"
	"net"
	"net/http"
	"net/url"
	"strings"
)

type CreateWebhookRequest struct {
	URL    string   `json:"url"`
	Events []string `json:"events"`
	Secret string   `json:"secret,omitempty"`
}

type WebhookSubscription struct {
	ID     string   `json:"id"`
	URL    string   `json:"url"`
	Events []string `json:"events"`
	Status string   `json:"status"`
}

func ValidateWebhookURL(rawURL string) error {
	u, err := url.ParseRequestURI(rawURL)
	if err != nil {
		return fmt.Errorf("invalid URL format: %w", err)
	}

	if u.Scheme != "https" {
		return errors.New("only HTTPS scheme is permitted for webhooks")
	}

	hostname := u.Hostname()
	if hostname == "" {
		return errors.New("missing hostname in target URL")
	}

	if hostname == "localhost" || strings.HasSuffix(hostname, ".local") {
		return errors.New("localhost and local domains are prohibited")
	}

	ips, err := net.LookupIP(hostname)
	if err != nil {
		return fmt.Errorf("host cannot be resolved: %w", err)
	}

	for _, ip := range ips {
		if ip.IsLoopback() {
			return errors.New("prohibited loopback address")
		}
		if ip.IsPrivate() {
			return errors.New("prohibited private RFC1918 address")
		}
		if ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() {
			return errors.New("prohibited link-local cloud metadata address")
		}
	}
	return nil
}

func WebhookRegisterHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method Not Allowed", http.StatusMethodNotAllowed)
		return
	}

	var req CreateWebhookRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON payload", http.StatusBadRequest)
		return
	}

	if err := ValidateWebhookURL(req.URL); err != nil {
		http.Error(w, fmt.Sprintf("SSRF / URL Validation error: %v", err), http.StatusBadRequest)
		return
	}

	if len(req.Events) == 0 {
		http.Error(w, "At least one event type must be subscribed", http.StatusBadRequest)
		return
	}

	sub := WebhookSubscription{
		ID:     "sub_01HZX8N29XYZ",
		URL:    req.URL,
		Events: req.Events,
		Status: "active",
	}

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	_ = json.NewEncoder(w).Encode(sub)
}

func main() {
	fmt.Println("Check public HTTPS:", ValidateWebhookURL("https://api.ozon.ru/webhooks"))
	fmt.Println("Check internal 127.0.0.1:", ValidateWebhookURL("https://127.0.0.1/admin"))
	fmt.Println("Check plain HTTP:", ValidateWebhookURL("http://public-api.com/hook"))
}

package main

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/http/httptest"
	"time"
)

var defaultWebhookTransport = &http.Transport{
	DialContext: (&net.Dialer{
		Timeout:   5 * time.Second,
		KeepAlive: 30 * time.Second,
	}).DialContext,
	MaxIdleConns:        1000,
	MaxIdleConnsPerHost: 100,
	IdleConnTimeout:     90 * time.Second,
	TLSHandshakeTimeout: 5 * time.Second,
	DisableCompression:  false,
}

var webhookHTTPClient = &http.Client{
	Transport: defaultWebhookTransport,
	Timeout:   10 * time.Second,
}

func SendWebhook(ctx context.Context, client *http.Client, targetURL string, payload []byte) error {
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, targetURL, bytes.NewReader(payload))
	if err != nil {
		return fmt.Errorf("failed to create request: %w", err)
	}

	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("User-Agent", "GoWorkout-Webhook-Platform/1.0")

	resp, err := client.Do(req)
	if err != nil {
		return fmt.Errorf("http request execution failed: %w", err)
	}
	defer resp.Body.Close()

	_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 1024*1024))

	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return fmt.Errorf("unexpected http response status: %d", resp.StatusCode)
	}
	return nil
}

func main() {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		fmt.Printf("Mock Server received %d bytes, UA: %s\n", len(body), r.Header.Get("User-Agent"))
		w.WriteHeader(http.StatusOK)
	}))
	defer server.Close()

	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
	defer cancel()

	payload := []byte(`{"event":"ping","timestamp":1718000000}`)
	if err := SendWebhook(ctx, webhookHTTPClient, server.URL, payload); err != nil {
		panic(err)
	}
	fmt.Println("Webhook delivered successfully.")
}

package main

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"net/url"
	"strings"
	"time"
)

func GenerateChallengeToken() string {
	b := make([]byte, 16)
	_, _ = rand.Read(b)
	return hex.EncodeToString(b)
}

func VerifyEndpointChallenge(ctx context.Context, client *http.Client, rawTargetURL string) (bool, error) {
	challenge := GenerateChallengeToken()

	parsedURL, err := url.Parse(rawTargetURL)
	if err != nil {
		return false, fmt.Errorf("invalid URL: %w", err)
	}

	q := parsedURL.Query()
	q.Set("challenge", challenge)
	parsedURL.RawQuery = q.Encode()

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, parsedURL.String(), nil)
	if err != nil {
		return false, err
	}
	req.Header.Set("User-Agent", "GoWorkout-Verification-Bot/1.0")

	resp, err := client.Do(req)
	if err != nil {
		return false, fmt.Errorf("verification request failed: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return false, fmt.Errorf("unexpected status code: %d", resp.StatusCode)
	}

	body, err := io.ReadAll(io.LimitReader(resp.Body, 512))
	if err != nil {
		return false, err
	}

	receivedChallenge := strings.TrimSpace(string(body))
	if receivedChallenge != challenge {
		return false, fmt.Errorf("challenge mismatch: expected %s, got %s", challenge, receivedChallenge)
	}

	return true, nil
}

func main() {
	clientServer := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		challenge := r.URL.Query().Get("challenge")
		if challenge == "" {
			w.WriteHeader(http.StatusBadRequest)
			return
		}
		w.Header().Set("Content-Type", "text/plain")
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(challenge))
	}))
	defer clientServer.Close()

	httpClient := &http.Client{Timeout: 3 * time.Second}
	ok, err := VerifyEndpointChallenge(context.Background(), httpClient, clientServer.URL)
	if err != nil {
		fmt.Printf("Verification error: %v\n", err)
	} else {
		fmt.Printf("Endpoint Verified Successfully: %v\n", ok)
	}
}

