import (
	"crypto/hmac"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/hex"
	"fmt"
	"strings"
)

type HMACSigner struct {
	secret []byte
}

func NewHMACSigner(secret string) *HMACSigner {
	return &HMACSigner{secret: []byte(secret)}
}

func (s *HMACSigner) Sign(payload []byte) string {
	mac := hmac.New(sha256.New, s.secret)
	mac.Write(payload)
	sum := mac.Sum(nil)
	return "sha256=" + hex.EncodeToString(sum)
}

func (s *HMACSigner) Verify(payload []byte, headerValue string) bool {
	if !strings.HasPrefix(headerValue, "sha256=") {
		return false
	}
	expectedSig := s.Sign(payload)
	return subtle.ConstantTimeCompare([]byte(headerValue), []byte(expectedSig)) == 1
}

func main() {
	signer := NewHMACSigner("whsec_prod_secret_token_123")
	payload := []byte(`{"event":"charge.refunded","amount":500}`)

	header := signer.Sign(payload)
	fmt.Printf("Generated Header: %s\n", header)

	valid := signer.Verify(payload, header)
	fmt.Printf("Verification result (valid): %v\n", valid)

	tamperedPayload := []byte(`{"event":"charge.refunded","amount":99999}`)
	invalid := signer.Verify(tamperedPayload, header)
	fmt.Printf("Verification result (tampered): %v\n", invalid)
}

package main

import (
	"bytes"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"math"
	"net/http"
	"net/http/httptest"
	"strconv"
	"time"
)

func WebhookAuthMiddleware(secret string) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			tsHeader := r.Header.Get("X-Webhook-Timestamp")
			sigHeader := r.Header.Get("X-Webhook-Signature")

			if tsHeader == "" || sigHeader == "" {
				http.Error(w, "Missing security headers", http.StatusUnauthorized)
				return
			}

			// 1. Проверка Clock Skew (до 5 минут)
			ts, err := strconv.ParseInt(tsHeader, 10, 64)
			if err != nil || math.Abs(float64(time.Now().UTC().Unix()-ts)) > 300 {
				http.Error(w, "Timestamp invalid or expired", http.StatusBadRequest)
				return
			}

			// 2. Чтение тела запроса с ограничением
			bodyBytes, err := io.ReadAll(io.LimitReader(r.Body, 1024*1024))
			if err != nil {
				http.Error(w, "Cannot read request body", http.StatusInternalServerError)
				return
			}
			_ = r.Body.Close()

			// 3. Вычисление ожидаемого HMAC
			toSign := []byte(fmt.Sprintf("%s.%s", tsHeader, string(bodyBytes)))
			mac := hmac.New(sha256.New, []byte(secret))
			mac.Write(toSign)
			expectedMAC := mac.Sum(nil)

			// 4. Декодирование входящей hex-подписи
			incomingMAC, err := hex.DecodeString(sigHeader)
			if err != nil || !hmac.Equal(expectedMAC, incomingMAC) {
				http.Error(w, "Invalid HMAC signature", http.StatusUnauthorized)
				return
			}

			// 5. Восстанавливаем Body для целевого хэндлера
			r.Body = io.NopCloser(bytes.NewReader(bodyBytes))
			next.ServeHTTP(w, r)
		})
	}
}

func main() {
	secret := "whsec_client_shared_secret_777"

	handler := WebhookAuthMiddleware(secret)(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		fmt.Printf("Business logic executed: %s\n", string(body))
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(`{"status":"processed"}`))
	}))

	ts := httptest.NewServer(handler)
	defer ts.Close()

	// Тестовый запрос
	now := strconv.FormatInt(time.Now().UTC().Unix(), 10)
	payload := `{"order_id":"123","status":"paid"}`
	mac := hmac.New(sha256.New, []byte(secret))
	mac.Write([]byte(now + "." + payload))
	signature := hex.EncodeToString(mac.Sum(nil))

	req, _ := http.NewRequest(http.MethodPost, ts.URL, bytes.NewReader([]byte(payload)))
	req.Header.Set("X-Webhook-Timestamp", now)
	req.Header.Set("X-Webhook-Signature", signature)

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		panic(err)
	}
	defer resp.Body.Close()
	fmt.Printf("Receiver returned status: %d\n", resp.StatusCode)
}

package main

import (
	"fmt"
	"sync"
	"time"
)

type Subscription struct {
	ID        string
	TargetURL string
	Secret    string
	Topics    []string
}

type Event struct {
	ID        string `json:"id"`
	Type      string `json:"type"`
	Timestamp int64  `json:"timestamp"`
	Payload   any    `json:"payload"`
}

type DispatchTask struct {
	EventID   string
	EventType string
	TargetURL string
	Secret    string
	Payload   any
}

type SubscriptionRegistry struct {
	mu            sync.RWMutex
	subscriptions []Subscription
}

func (r *SubscriptionRegistry) Add(sub Subscription) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.subscriptions = append(r.subscriptions, sub)
}

func (r *SubscriptionRegistry) FindSubscribers(eventType string) []Subscription {
	r.mu.RLock()
	defer r.mu.RUnlock()
	var matches []Subscription
	for _, sub := range r.subscriptions {
		for _, topic := range sub.Topics {
			if topic == "*" || topic == eventType {
				matches = append(matches, sub)
				break
			}
		}
	}
	return matches
}

type EventDispatcher struct {
	registry *SubscriptionRegistry
	outQueue chan DispatchTask
}

func NewEventDispatcher(reg *SubscriptionRegistry, queueSize int) *EventDispatcher {
	return &EventDispatcher{
		registry: reg,
		outQueue: make(chan DispatchTask, queueSize),
	}
}

func (d *EventDispatcher) Dispatch(event Event) int {
	subscribers := d.registry.FindSubscribers(event.Type)
	for _, sub := range subscribers {
		task := DispatchTask{
			EventID:   event.ID,
			EventType: event.Type,
			TargetURL: sub.TargetURL,
			Secret:    sub.Secret,
			Payload:   event.Payload,
		}
		d.outQueue <- task
	}
	return len(subscribers)
}

func main() {
	reg := &SubscriptionRegistry{}
	reg.Add(Subscription{ID: "sub_1", TargetURL: "https://crm.corp.ru/hooks", Secret: "sec_1", Topics: []string{"order.paid"}})
	reg.Add(Subscription{ID: "sub_2", TargetURL: "https://warehouse.ru/wh", Secret: "sec_2", Topics: []string{"order.*", "order.paid"}})
	reg.Add(Subscription{ID: "sub_3", TargetURL: "https://audit.ru/log", Secret: "sec_3", Topics: []string{"*"}})
	reg.Add(Subscription{ID: "sub_4", TargetURL: "https://billing.ru/invoices", Secret: "sec_4", Topics: []string{"invoice.created"}})

	dispatcher := NewEventDispatcher(reg, 100)

	evt := Event{
		ID:        "evt_99812",
		Type:      "order.paid",
		Timestamp: time.Now().Unix(),
		Payload:   map[string]any{"order_id": "ord_555", "total": 4500},
	}

	count := dispatcher.Dispatch(evt)
	fmt.Printf("Event %s dispatched to %d subscribers\n", evt.Type, count)

	// Вычитываем задачи из очереди доставки
	for i := 0; i < count; i++ {
		task := <-dispatcher.outQueue
