import (
	"context"
	"errors"
	"fmt"
	"net"
	"net/http"
	"syscall"
	"time"
)

var (
	ErrBlockedIP = errors.New("webhook destination IP is in restricted private/link-local subnet (SSRF protection)")
)

// Список запрещенных приватных, служебных и облачных диапазонов
var privateIPBlocks []*net.IPNet

func init() {
	cidrs := []string{
		"127.0.0.0/8",          // IPv4 loopback
		"::1/128",               // IPv6 loopback
		"10.0.0.0/8",            // RFC 1918
		"172.16.0.0/12",         // RFC 1918
		"192.168.0.0/16",        // RFC 1918
		"169.254.0.0/16",        // IPv4 Link-Local / Cloud Instance Metadata
		"fe80::/10",             // IPv6 Link-Local
		"fc00::/7",              // IPv6 Unique Local
		"0.0.0.0/8",             // "This host on this network"
		"100.64.0.0/10",         // Shared Address Space (CGNAT)
	}

	for _, cidr := range cidrs {
		_, block, err := net.ParseCIDR(cidr)
		if err != nil {
			panic(err)
		}
		privateIPBlocks = append(privateIPBlocks, block)
	}
}

// IsRestrictedIP проверяет, относится ли IP к приватным/служебным диапазонам
func IsRestrictedIP(ip net.IP) bool {
	if ip.IsLoopback() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() || ip.IsPrivate() {
		return true
	}
	for _, block := range privateIPBlocks {
		if block.Contains(ip) {
			return true
		}
	}
	return false
}

// NewSafeHTTPClient создает HTTP-клиент, защищенный от DNS Rebinding и SSRF
func NewSafeHTTPClient(timeout time.Duration) *http.Client {
	dialer := &net.Dialer{
		Timeout:   timeout,
		KeepAlive: 30 * time.Second,
		// Control вызывается ПОСЛЕ DNS-резолвинга конкретного IP, но ДО connect(2)
		Control: func(network, address string, c syscall.RawConn) error {
			host, _, err := net.SplitHostPort(address)
			if err != nil {
				return fmt.Errorf("invalid address %s: %w", address, err)
			}

			ip := net.ParseIP(host)
			if ip == nil {
				return fmt.Errorf("unable to parse IP: %s", host)
			}

			if IsRestrictedIP(ip) {
				return fmt.Errorf("%w: attempted connection to %s", ErrBlockedIP, ip.String())
			}

			return nil
		},
	}

	transport := &http.Transport{
		DialContext:           dialer.DialContext,
		ForceAttemptHTTP2:     true,
		MaxIdleConns:          100,
		IdleConnTimeout:       90 * time.Second,
		TLSHandshakeTimeout:   5 * time.Second,
		ExpectContinueTimeout: 1 * time.Second,
	}

	return &http.Client{
		Transport: transport,
		Timeout:   timeout,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			// Запрещаем редиректы, чтобы атакующий не сделал 302 на внутренний IP
			return http.ErrUseLastResponse
		},
	}
}

func main() {
	client := NewSafeHTTPClient(3 * time.Second)

	testURLs := []string{
		"http://127.0.0.1:8080/secret",
		"http://169.254.169.254/latest/meta-data/",
		"http://10.100.0.15/metrics",
		"http://8.8.8.8", // Публичный DNS Google
	}

	for _, u := range testURLs {
		req, _ := http.NewRequestWithContext(context.Background(), http.MethodGet, u, nil)
		resp, err := client.Do(req)
		if err != nil {
			fmt.Printf("[BLOCKED/FAIL] URL: %-42s -> Ошибка: %v\n", u, err)
		} else {
			resp.Body.Close()
			fmt.Printf("[ALLOWED]      URL: %-42s -> Статус: %d\n", u, resp.StatusCode)
		}
	}
}

package main

import (
	"fmt"
	"math"
	"math/rand/v2"
	"time"
)

type BackoffStrategy struct {
	BaseDelay time.Duration
	MaxDelay  time.Duration
}

// NoJitter возвращает строгую экспоненциальную задержку: Base * 2^attempt
func (s *BackoffStrategy) NoJitter(attempt int) time.Duration {
	if attempt > 30 {
		return s.MaxDelay
	}
	multiplier := math.Pow(2, float64(attempt))
	delay := time.Duration(float64(s.BaseDelay) * multiplier)
	if delay > s.MaxDelay {
		return s.MaxDelay
	}
	return delay
}

// EqualJitter возвращает задержку: Delay/2 + rand(0, Delay/2)
func (s *BackoffStrategy) EqualJitter(attempt int) time.Duration {
	ceiling := s.NoJitter(attempt)
	half := ceiling / 2
	if half <= 0 {
		return ceiling
	}
	randomPart := time.Duration(rand.Int64N(int64(half)))
	return half + randomPart
}

// FullJitter возвращает задержку: rand(0, min(MaxDelay, Base * 2^attempt))
func (s *BackoffStrategy) FullJitter(attempt int) time.Duration {
	ceiling := s.NoJitter(attempt)
	if ceiling <= 0 {
		return s.BaseDelay
	}
	// rand.Int64N возвращает значение в полуинтервале [0, n)
	return time.Duration(rand.Int64N(int64(ceiling)))
}

func main() {
	strategy := BackoffStrategy{
		BaseDelay: 1 * time.Second,
		MaxDelay:  30 * time.Second,
	}

	fmt.Println("=== Сравнение стратегий бэкоффа для попытки № 3 (Детерминированный предел = 8 сек) ===")
	fmt.Printf("No Jitter:    %v\n", strategy.NoJitter(3))

	fmt.Println("\nВыборка Equal Jitter (диапазон 4с .. 8с):")
	for i := 0; i < 5; i++ {
		fmt.Printf("  Запуск %d: %v\n", i+1, strategy.EqualJitter(3).Round(time.Millisecond))
	}

	fmt.Println("\nВыборка Full Jitter (диапазон 0с .. 8с):")
	for i := 0; i < 5; i++ {
		fmt.Printf("  Запуск %d: %v\n", i+1, strategy.FullJitter(3).Round(time.Millisecond))
	}

	// Симуляция распределения для 1000 горутин
	const samples = 1000
	var buckets [8]int // корзины по 1 секунде (0..1с, 1..2с, ..., 7..8с)

	for i := 0; i < samples; i++ {
		delay := strategy.FullJitter(3)
		sec := int(delay.Seconds())
		if sec >= 8 {
			sec = 7
		}
		buckets[sec]++
	}

	fmt.Println("\nГистограмма распределения 1000 повторов (Full Jitter) по секундам:")
	for sec, count := range buckets {
		bar := ""
		for b := 0; b < count/15; b++ {
			bar += "█"
		}
		fmt.Printf("  [%dс - %dс]: %3d запросов | %s\n", sec, sec+1, count, bar)
	}
}

package main

import (
	"context"
	"fmt"
	"sync"
	"sync/atomic"
	"time"
)

type TargetSubscriber struct {
	ID  string
	URL string
}

type DispatchResult struct {
	TotalSent  int64
	Successful int64
	Failed     int64
	Duration   time.Duration
}

type BroadcastDispatcher struct {
	maxConcurrency int
	sem            chan struct{}
}

func NewBroadcastDispatcher(maxConcurrency int) *BroadcastDispatcher {
	return &BroadcastDispatcher{
		maxConcurrency: maxConcurrency,
		sem:            make(chan struct{}, maxConcurrency),
	}
}

// Broadcast отправляет полезную нагрузку всем подписчикам с жестким ограничением параллелизма
func (d *BroadcastDispatcher) Broadcast(ctx context.Context, payload []byte, subs []TargetSubscriber) DispatchResult {
	start := time.Now()
	var (
		totalSent  atomic.Int64
		successful atomic.Int64
		failed     atomic.Int64
		wg         sync.WaitGroup
	)

	for _, sub := range subs {
		// Проверяем, не отменен ли общий контекст перед запуском
		if ctx.Err() != nil {
			break
		}

		// Захватываем слот семафора с учетом отмены контекста
		select {
		case <-ctx.Done():
			break
		case d.sem <- struct{}{}:
		}

		wg.Add(1)
		go func(target TargetSubscriber) {
			defer func() {
				<-d.sem // Освобождаем слот семафора
				wg.Done()
			}()

			totalSent.Add(1)
			err := d.sendToSubscriber(ctx, target, payload)
			if err != nil {
				failed.Add(1)
			} else {
				successful.Add(1)
			}
		}(sub)
	}

	wg.Wait()

	return DispatchResult{
		TotalSent:  totalSent.Load(),
		Successful: successful.Load(),
		Failed:     failed.Load(),
		Duration:   time.Since(start),
	}
}

// Симуляция отправки HTTP POST запроса
func (d *BroadcastDispatcher) sendToSubscriber(ctx context.Context, target TargetSubscriber, payload []byte) error {
	// Имитация сетевой задержки от 10 до 30 мс
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-time.After(20 * time.Millisecond):
	}
	return nil
}

func main() {
	// Подготавливаем 100 подписчиков
	subscribers := make([]TargetSubscriber, 100)
	for i := 0; i < 100; i++ {
		subscribers[i] = TargetSubscriber{
			ID:  fmt.Sprintf("client-%03d", i+1),
			URL: fmt.Sprintf("https://partner-%03d.ru/webhook", i+1),
		}
	}

	// Ограничиваем параллелизм 10 одновременными запросами
	dispatcher := NewBroadcastDispatcher(10)

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	fmt.Printf("Старт рассылки по %d подписчикам с семафором на %d горутин...\n", len(subscribers), dispatcher.maxConcurrency)
	res := dispatcher.Broadcast(ctx, []byte(`{"event":"flash_sale.started"}`), subscribers)

	fmt.Printf("\n=== Результаты рассылки ===\n")
	fmt.Printf("Всего запущено:  %d\n", res.TotalSent)
	fmt.Printf("Успешно:         %d\n", res.Successful)
	fmt.Printf("Ошибок:          %d\n", res.Failed)
	fmt.Printf("Время рассылки:  %v\n", res.Duration.Round(time.Millisecond))
}

