)

var (
	ErrRedirectDisallowed = errors.New("webhook delivery: redirects are strictly prohibited for security reasons")
	ErrCrossHostRedirect  = errors.New("webhook delivery: cross-host redirect detected (SSRF protection)")
	ErrInsecureDowngrade  = errors.New("webhook delivery: protocol downgrade from HTTPS to HTTP is forbidden")
)

// PolicyNoRedirects полностью запрещает любые перенаправления (как в Stripe API)
func NewNoRedirectClient() *http.Client {
	return &http.Client{
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			// Возврат http.ErrUseLastResponse останавливает клиент и возвращает ответ 3xx как есть
			return http.ErrUseLastResponse
		},
	}
}

// PolicyStrictSameHost разрешает ровно 1 редирект в рамках одного и того же хоста
func NewStrictSameHostClient() *http.Client {
	return &http.Client{
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			if len(via) >= 1 {
				return fmt.Errorf("%w: maximum 1 redirect allowed", ErrRedirectDisallowed)
			}

			originURL := via[0].URL
			targetURL := req.URL

			// Запрещаем переход на другой домен
			if originURL.Host != targetURL.Host {
				return fmt.Errorf("%w: cannot redirect from %s to %s",
					ErrCrossHostRedirect, originURL.Host, targetURL.Host)
			}

			// Запрещаем понижение безопасности с HTTPS до HTTP
			if originURL.Scheme == "https" && targetURL.Scheme == "http" {
				return ErrInsecureDowngrade
			}

			// Очищаем чувствительные токены при перенаправлении
			req.Header.Del("Authorization")

			return nil
		},
	}
}

func main() {
	// Создаем тестовый сервер, имитирующий уязвимый редирект на метаданные AWS
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/redirect-to-metadata" {
			http.Redirect(w, r, "http://169.254.169.254/secret", http.StatusFound)
			return
		}
		if r.URL.Path == "/redirect-same-host" {
			http.Redirect(w, r, "/valid-endpoint", http.StatusFound)
			return
		}
		w.WriteHeader(http.StatusOK)
		w.Write([]byte("Payload delivered successfully"))
	}))
	defer ts.Close()

	fmt.Println("=== Тестирование NoRedirectClient (Политика Stripe) ===")
	noRedirClient := NewNoRedirectClient()
	resp, err := noRedirClient.Get(ts.URL + "/redirect-to-metadata")
	if err != nil {
		fmt.Printf("Ошибка: %v\n", err)
	} else {
		fmt.Printf("Статус ответа: %d (Редирект НЕ совершен, возвращен 302 как результат)\n", resp.StatusCode)
		resp.Body.Close()
	}

	fmt.Println("\n=== Тестирование StrictSameHostClient (Защита от SSRF) ===")
	sameHostClient := NewStrictSameHostClient()

	// Попытка междоменного редиректа на внутреннюю сеть
	_, err = sameHostClient.Get(ts.URL + "/redirect-to-metadata")
	if err != nil {
		var urlErr *url.Error
		if errors.As(err, &urlErr) {
			fmt.Printf("Успешно заблокировано: %v\n", urlErr.Err)
		} else {
			fmt.Printf("Ошибка: %v\n", err)
		}
	}

	// Легитимный редирект на тот же хост
	respValid, err := sameHostClient.Get(ts.URL + "/redirect-same-host")
	if err != nil {
		fmt.Printf("Неожиданная ошибка: %v\n", err)
	} else {
		fmt.Printf("Успешный редирект на тот же хост, финальный статус: %d\n", respValid.StatusCode)
		respValid.Body.Close()
	}
}

package main

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
)

const (
	// MaxWebhookPayloadSize - жесткий лимит полезной нагрузки (256 KB)
	MaxWebhookPayloadSize = 256 * 1024
)

var (
	ErrPayloadTooLarge = errors.New("webhook payload exceeds maximum permitted size of 256KB")
)

// WebhookEnvelope представляет метаданные события
type WebhookEnvelope struct {
	EventID   string          `json:"event_id"`
	EventType string          `json:"event_type"`
	Payload   json.RawMessage `json:"payload,omitempty"`
	BlobURL   string          `json:"blob_url,omitempty"` // Заполняется, если тело превысило 256КБ
}

// ValidateAndPreparePayload проверяет размер и при необходимости переключается на S3-ссылку
func ValidateAndPreparePayload(eventID, eventType string, rawData []byte) (*WebhookEnvelope, error) {
	if len(rawData) <= MaxWebhookPayloadSize {
		return &WebhookEnvelope{
			EventID:   eventID,
			EventType: eventType,
			Payload:   rawData,
		}, nil
	}

	// Если полезная нагрузка превышает 256КБ, применяем паттерн Claim Check (S3 Offloading)
	blobURL := fmt.Sprintf("https://s3.company.ru/webhook-payloads/%s.json", eventID)
	fmt.Printf("[OFFLOAD] Размер полезной нагрузки %d байт > 256КБ! Сохранено в S3: %s\n", len(rawData), blobURL)

	return &WebhookEnvelope{
		EventID:   eventID,
		EventType: eventType,
		BlobURL:   blobURL,
	}, nil
}

// ClientReceiverHandler демонстрирует защиту приемника через http.MaxBytesReader
func ClientReceiverHandler(w http.ResponseWriter, r *http.Request) {
	// Защита приемника: читаем максимум 256KB + 1 байт для обнаружения превышения
	r.Body = http.MaxBytesReader(w, r.Body, MaxWebhookPayloadSize)

	body, err := io.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "Payload Too Large or Read Error", http.StatusRequestEntityTooLarge)
		return
	}

	w.WriteHeader(http.StatusOK)
	w.Write([]byte(fmt.Sprintf("Received %d bytes", len(body))))
}

func main() {
	// Кейс 1: Маленький вебхук (500 байт)
	smallData := []byte(`{"order_id": "ord_1001", "amount": 2500.50}`)
	envSmall, _ := ValidateAndPreparePayload("evt_1", "order.created", smallData)
	encodedSmall, _ := json.Marshal(envSmall)
	fmt.Printf("Кейс 1 (Норма): Готов к отправке, размер JSON = %d байт\n", len(encodedSmall))

	// Кейс 2: Огромный вебхук (500 КБ данных)
	hugeData := bytes.Repeat([]byte("A"), 500*1024)
	envHuge, _ := ValidateAndPreparePayload("evt_2", "catalog.synced", hugeData)
	encodedHuge, _ := json.Marshal(envHuge)
	fmt.Printf("Кейс 2 (S3 Offload): Итоговый размер конверта вебхука = %d байт\n", len(encodedHuge))

	// Кейс 3: Проверка защиты приемника через httptest
	ts := httptest.NewServer(http.HandlerFunc(ClientReceiverHandler))
	defer ts.Close()

	// Отправляем тело размером 300 КБ прямо в эндпоинт приемника
	oversizedBody := bytes.NewReader(bytes.Repeat([]byte("X"), 300*1024))
	resp, _ := http.Post(ts.URL, "application/json", oversizedBody)
	defer resp.Body.Close()

	fmt.Printf("Кейс 3 (Защита сервера): HTTP Статус при отправке 300КБ = %d %s\n",
		resp.StatusCode, http.StatusText(resp.StatusCode))
}

package main

import (
	"bytes"
	"compress/gzip"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"sync"
)

// GzipPool оптимизирует аллокации компрессора при высокой нагрузке
var gzipWriterPool = sync.Pool{
	New: func() any {
		w, _ := gzip.NewWriterLevel(nil, gzip.BestSpeed)
		return w
	},
}

// CompressGzip сжимает полезную нагрузку с переиспользованием gzip.Writer
func CompressGzip(data []byte) ([]byte, error) {
	buf := new(bytes.Buffer)
	gz := gzipWriterPool.Get().(*gzip.Writer)
	defer gzipWriterPool.Put(gz)

	gz.Reset(buf)
	if _, err := gz.Write(data); err != nil {
		return nil, err
	}
	if err := gz.Close(); err != nil {
		return nil, err
	}

	return buf.Bytes(), nil
}

// WebhookGzipMiddleware автоматически распаковывает тело входящего вебхука
func WebhookGzipMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Header.Get("Content-Encoding") == "gzip" {
			gzReader, err := gzip.NewReader(r.Body)
			if err != nil {
				http.Error(w, "Malformed Gzip Body", http.StatusBadRequest)
				return
			}
			defer gzReader.Close()
			// Подменяем тело на поток распаковщика
			r.Body = gzReader
		}
		next(w, r)
	}
}

func main() {
	// Создаем тестовый JSON с избыточными данными
	rawJSON := []byte(`{
		"event": "payment.succeeded",
		"customer": {"name": "Иван Иванов", "account": "ACC-9988221144"},
		"description": "Повторяющийся текст для демонстрации эффективности сжатия gzip алгоритмом. Повторяющийся текст для демонстрации эффективности сжатия."
	}`)

	// Сжимаем
	compressed, err := CompressGzip(rawJSON)
	if err != nil {
		panic(err)
	}

	ratio := float64(len(compressed)) / float64(len(rawJSON)) * 100
	fmt.Printf("Размер исходного JSON: %d байт\n", len(rawJSON))
	fmt.Printf("Размер после сжатия:  %d байт (Сжатие до %.1f%% от оригинала)\n", len(compressed), ratio)

	// Тестовый HTTP сервер с распаковкой
	handler := WebhookGzipMiddleware(func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		fmt.Printf("[SERVER] Успешно получено и распаковано: %d байт JSON\n", len(body))
		w.WriteHeader(http.StatusOK)
		w.Write([]byte("OK"))
	})

	ts := httptest.NewServer(handler)
	defer ts.Close()

	// Отправка сжатого вебхука
	req, _ := http.NewRequest(http.MethodPost, ts.URL, bytes.NewReader(compressed))
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Content-Encoding", "gzip")

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		panic(err)
	}
	defer resp.Body.Close()

	fmt.Printf("HTTP Статус доставки: %d %s\n", resp.StatusCode, http.StatusText(resp.StatusCode))
}

package main

import (
	"context"
	"fmt"
	"sync"
	"time"

	"golang.org/x/time/rate"
)

type EndpointLimiterRegistry struct {
	defaultRPS   rate.Limit
	defaultBurst int
	limiters     map[string]*rate.Limiter
	mu           sync.RWMutex
}

func NewEndpointLimiterRegistry(rps float64, burst int) *EndpointLimiterRegistry {
	return &EndpointLimiterRegistry{
		defaultRPS:   rate.Limit(rps),
		defaultBurst: burst,
		limiters:     make(map[string]*rate.Limiter),
	}
}

// GetLimiter возвращает или инициализирует персональный Token Bucket для эндпоинта
func (r *EndpointLimiterRegistry) GetLimiter(endpointKey string) *rate.Limiter {
	r.mu.RLock()
	limiter, exists := r.limiters[endpointKey]
	r.mu.RUnlock()

	if exists {
		return limiter
	}

	r.mu.Lock()
	defer r.mu.Unlock()

	// Double-check locking
	if limiter, exists = r.limiters[endpointKey]; exists {
		return limiter
	}

	limiter = rate.NewLimiter(r.defaultRPS, r.defaultBurst)
	r.limiters[endpointKey] = limiter
	return limiter
}

// WebhookSender демонстрирует отправку с задержкой по Token Bucket
type WebhookSender struct {
	registry *EndpointLimiterRegistry
}

func (s *WebhookSender) Deliver(ctx context.Context, endpoint string, eventID string) error {
	limiter := s.registry.GetLimiter(endpoint)

	// Wait блокирует горутину до тех пор, пока токен не станет доступен
	startWait := time.Now()
	if err := limiter.Wait(ctx); err != nil {
		return fmt.Errorf("rate limit wait cancelled: %w", err)
	}
	waitDuration := time.Since(startWait)

	// Имитация быстрой отправки
	fmt.Printf("[%s] Отправлен %s на %s (Ожидание токена: %v)\n",
		time.Now().Format("15:04:05.000"), eventID, endpoint, waitDuration.Round(time.Millisecond))
	return nil
}

func main() {
	// Лимит: 5 запросов в секунду на эндпоинт, максимальный burst = 2
	registry := NewEndpointLimiterRegistry(5.0, 2)
	sender := WebhookSender{registry: registry}

	ctx := context.Background()
	endpointA := "https://api.small-shop.ru/webhook"
	endpointB := "https://api.big-corp.ru/webhook"

	var wg sync.WaitGroup

	// Запускаем всплеск из 6 одновременных событий на endpointA
	fmt.Println("=== Старт всплеска из 6 событий на endpointA (Лимит: 5 RPS, Burst: 2) ===")
	for i := 1; i <= 6; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			sender.Deliver(ctx, endpointA, fmt.Sprintf("evt-A-%d", id))
		}(i)
	}

	// Параллельно отправляем событие на независимый endpointB
	wg.Add(1)
	go func() {
		defer wg.Done()
		time.Sleep(50 * time.Millisecond)
		sender.Deliver(ctx, endpointB, "evt-B-1")
	}()

	wg.Wait()
	fmt.Println("=== Все события успешно доставлены без превышения скорости ===")
}

package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/hex"
	"errors"
	"fmt"
	"strconv"
	"time"
)

var (
	ErrTimestampTooOld   = errors.New("webhook rejected: timestamp is older than tolerance window (potential replay attack)")
	ErrTimestampInFuture = errors.New("webhook rejected: timestamp is too far in future (clock skew issue)")
	ErrInvalidSignature  = errors.New("webhook rejected: HMAC signature verification failed")
)

// SignWithTimestamp генерирует подпись от timestamp.body
func SignWithTimestamp(secret []byte, payload []byte, t time.Time) (string, string) {
	timestampStr := strconv.FormatInt(t.Unix(), 10)
	mac := hmac.New(sha256.New, secret)

	// Конкатенируем метку времени и полезную нагрузку через точку
	mac.Write([]byte(timestampStr))
	mac.Write([]byte("."))
	mac.Write(payload)

	signature := hex.EncodeToString(mac.Sum(nil))
	return timestampStr, signature
}

// VerifyWebhookAndReplay валидирует подпись и проверяет допустимое окно времени
func VerifyWebhookAndReplay(secret []byte, payload []byte, timestampHeader, signatureHeader string, tolerance time.Duration) error {
	// 1. Парсинг метки времени
	tsInt, err := strconv.ParseInt(timestampHeader, 10, 64)
	if err != nil {
		return fmt.Errorf("invalid timestamp format: %w", err)
	}

	eventTime := time.Unix(tsInt, 0)
	now := time.Now()

	// 2. Проверка окна устаревания (Tolerance Window)
	if now.Sub(eventTime) > tolerance {
		return fmt.Errorf("%w: delta=%v > tolerance=%v", ErrTimestampTooOld, now.Sub(eventTime), tolerance)
	}
	// Защита от сообщений из "будущего" (при рассинхронизации NTP серверов)
	if eventTime.Sub(now) > tolerance {
		return fmt.Errorf("%w: message is from the future", ErrTimestampInFuture)
	}

	// 3. Вычисление ожидаемого HMAC
	mac := hmac.New(sha256.New, secret)
	mac.Write([]byte(timestampHeader))
	mac.Write([]byte("."))
	mac.Write(payload)
	expectedMAC := mac.Sum(nil)

	expectedSigHex := hex.EncodeToString(expectedMAC)

	// 4. Безопасное сравнение подписей с защитой от тайминг-атак
	if subtle.ConstantTimeCompare([]byte(expectedSigHex), []byte(signatureHeader)) != 1 {
		return ErrInvalidSignature
	}

	return nil
}

func main() {
	secret := []byte("whsec_SuperSecureSigningKey2026")
	payload := []byte(`{"event":"wallet.credited","amount":50000}`)
	tolerance := 5 * time.Minute

	// Кейс 1: Нормальная валидная отправка
	now := time.Now()
	tsStr, sig := SignWithTimestamp(secret, payload, now)
	err := VerifyWebhookAndReplay(secret, payload, tsStr, sig, tolerance)
	fmt.Printf("Кейс 1 (Свежий запрос): Ошибка = %v (Успешно принят)\n", err)

	// Кейс 2: Попытка Replay Attack перехваченного запроса через 15 минут
	oldTime := time.Now().Add(-15 * time.Minute)
	oldTsStr, oldSig := SignWithTimestamp(secret, payload, oldTime)
	err = VerifyWebhookAndReplay(secret, payload, oldTsStr, oldSig, tolerance)
	fmt.Printf("Кейс 2 (Replay атака через 15 мин): Ошибка = %v\n", err)

	// Кейс 3: Злоумышленник пытается обновить X-Timestamp на текущий, не зная секретный ключ
	currentTsStr := strconv.FormatInt(time.Now().Unix(), 10)
	err = VerifyWebhookAndReplay(secret, payload, currentTsStr, oldSig, tolerance)
	fmt.Printf("Кейс 3 (Подмена timestamp без знания ключа): Ошибка = %v\n", err)
}

package main

import (
	"context"
	"fmt"
	"sync"
	"sync/atomic"
	"time"

	"golang.org/x/time/rate"
)

// GlobalEgressLimiter управляет суммарной исходящей нагрузкой кластера
type GlobalEgressLimiter struct {
	rpsLimiter  *rate.Limiter
	byteLimiter *rate.Limiter
	droppedReqs atomic.Int64
	sentBytes   atomic.Int64
}

// NewGlobalEgressLimiter создает лимитер с ограничением по RPS и по байтам/сек
func NewGlobalEgressLimiter(maxRPS float64, burstRPS int, maxBytesPerSec float64, burstBytes int) *GlobalEgressLimiter {
	return &GlobalEgressLimiter{
		rpsLimiter:  rate.NewLimiter(rate.Limit(maxRPS), burstRPS),
		byteLimiter: rate.NewLimiter(rate.Limit(maxBytesPerSec), burstBytes),
	}
}

// AcquirePermit резервирует право на отправку вебхука заданного размера
func (l *GlobalEgressLimiter) AcquirePermit(ctx context.Context, payloadSize int) error {
	// 1. Проверяем лимит запросов в секунду (RPS)
	if err := l.rpsLimiter.Wait(ctx); err != nil {
		l.droppedReqs.Add(1)
		return fmt.Errorf("egress RPS limit exceeded: %w", err)
	}

	// 2. Проверяем лимит сетевой пропускной способности (Bandwidth)
	// Резервируем N токенов байт
	reservation := l.byteLimiter.ReserveN(time.Now(), payloadSize)
	if !reservation.OK() {
		l.droppedReqs.Add(1)
		return fmt.Errorf("payload size %d exceeds egress burst capacity", payloadSize)
	}

	delay := reservation.Delay()
	if delay > 0 {
		select {
		case <-time.After(delay):
		case <-ctx.Done():
			reservation.Cancel()
			l.droppedReqs.Add(1)
			return ctx.Err()
		}
	}

	l.sentBytes.Add(int64(payloadSize))
	return nil
}

func (l *GlobalEgressLimiter) Stats() (int64, int64) {
	return l.sentBytes.Load(), l.droppedReqs.Load()
}

func main() {
	// Ограничение: 10 RPS и максимум 100 КБ/сек сетевого трафика
	egressLimiter := NewGlobalEgressLimiter(10.0, 5, 100*1024, 50*1024)

	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()

	var wg sync.WaitGroup

	fmt.Println("=== Запуск симуляции отправки 15 вебхуков через Global Egress Limiter ===")
	start := time.Now()

	for i := 1; i <= 15; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			payloadSize := 10 * 1024 // 10 КБ на запрос

			err := egressLimiter.AcquirePermit(ctx, payloadSize)
			if err != nil {
				fmt.Printf("[%s] Запрос #%02d: ОТКЛОНЕН/ОТМЕНЕН (%v)\n",
					time.Now().Format("15:04:05.000"), id, err)
			} else {
				fmt.Printf("[%s] Запрос #%02d: Успешно отправлен в сеть (%d КБ)\n",
					time.Now().Format("15:04:05.000"), id, payloadSize/1024)
			}
		}(i)
	}

	wg.Wait()
	elapsed := time.Since(start)

	sentBytes, drops := egressLimiter.Stats()
	fmt.Printf("\n=== Итоги работы Egress Limiter за %v ===\n", elapsed.Round(time.Millisecond))
	fmt.Printf("Всего передано данных: %d КБ\n", sentBytes/1024)
	fmt.Printf("Дропов / Отмен:       %d\n", drops)
}

package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"sync/atomic"
	"time"
)

type WebhookTask struct {
	ID        string `json:"id"`
	Priority  string `json:"priority"` // "HIGH" (платежи) или "LOW" (аналитика)
	Payload   string `json:"payload"`
	CreatedAt time.Time
}

type BackpressureQueue struct {
	tasks         chan WebhookTask
	capacity      int64
	highWatermark int64 // 80% от capacity
	currentSize   atomic.Int64
	isDegraded    atomic.Bool
}

func NewBackpressureQueue(capacity int64) *BackpressureQueue {
	return &BackpressureQueue{
		tasks:         make(chan WebhookTask, capacity),
		capacity:      capacity,
		highWatermark: int64(float64(capacity) * 0.8),
	}
}

func (q *BackpressureQueue) Enqueue(task WebhookTask) bool {
	cur := q.currentSize.Load()

	// Если достигли критического уровня 80%, активируем degraded mode
	if cur >= q.highWatermark {
		q.isDegraded.Store(true)

		// В деградированном режиме принимаем только критические платежные события
		if task.Priority != "HIGH" {
			return false // Отклоняем низкоприоритетные задачи
		}
	} else {
		q.isDegraded.Store(false)
	}

	select {
	case q.tasks <- task:
		q.currentSize.Add(1)
		return true
	default:
		// Очередь физически полна на 100%
		return false
	}
}

func (q *BackpressureQueue) Dequeue() (WebhookTask, bool) {
	select {
	case task := <-q.tasks:
		q.currentSize.Add(-1)
		return task, true
	default:
		return WebhookTask{}, false
	}
}

// HTTP API Gateway с механизмом Backpressure
func WebhookIngestHandler(q *BackpressureQueue) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		var task WebhookTask
		if err := json.NewDecoder(r.Body).Decode(&task); err != nil {
			http.Error(w, "Bad Request", http.StatusBadRequest)
			return
		}
		task.CreatedAt = time.Now()

		accepted := q.Enqueue(task)
		if !accepted {
			w.Header().Set("Retry-After", "10")
			w.Header().Set("X-System-Status", "Degraded")
			http.Error(w, "Service Overloaded: delivery queue high watermark reached", http.StatusTooManyRequests)
			return
		}

		w.WriteHeader(http.StatusAccepted)
		w.Write([]byte(`{"status":"enqueued"}`))
	}
}

func main() {
	// Создаем компактную очередь на 10 элементов с порогом 8 элементов
	queue := NewBackpressureQueue(10)
	handler := WebhookIngestHandler(queue)
	ts := httptest.NewServer(handler)
	defer ts.Close()

	fmt.Println("=== Симуляция наполнения очереди до порога перегрузки (Backpressure) ===")

	// Наполняем очередь 8 обычными задачами
	for i := 1; i <= 8; i++ {
		queue.Enqueue(WebhookTask{ID: fmt.Sprintf("task-%d", i), Priority: "LOW"})
	}
	fmt.Printf("Текущий размер очереди: %d / %d (High Watermark = %d, Degraded = %v)\n",
		queue.currentSize.Load(), queue.capacity, queue.highWatermark, queue.isDegraded.Load())

	// Попытка отправить LOW приоритет через HTTP в момент перегрузки
	reqLow, _ := http.NewRequest(http.MethodPost, ts.URL,
		jsonReader(`{"id":"task-9-low","priority":"LOW","payload":"user.avatar_updated"}`))
	respLow, _ := http.DefaultClient.Do(reqLow)
	fmt.Printf("Отправка LOW приоритета: HTTP Статус = %d %s (Retry-After: %s)\n",
		respLow.StatusCode, http.StatusText(respLow.StatusCode), respLow.Header.Get("Retry-After"))

	// Отправка HIGH приоритета (платеж) в тот же момент
	reqHigh, _ := http.NewRequest(http.MethodPost, ts.URL,
		jsonReader(`{"id":"task-10-high","priority":"HIGH","payload":"payment.captured"}`))
	respHigh, _ := http.DefaultClient.Do(reqHigh)
	fmt.Printf("Отправка HIGH приоритета: HTTP Статус = %d %s\n",
		respHigh.StatusCode, http.StatusText(respHigh.StatusCode))
}

func jsonReader(s string) *http.Request {
	req, _ := http.NewRequest(http.MethodPost, "", nil)
	return req
}

